{
  "kind": "family budget bot",
  "asked": [
    "track spending",
    "set monthly budgets",
    "plan for Christmas",
    "plan for summer camp",
    "pay down credit card",
    "see charts"
  ],
  "also_needed": [
    "import bank data",
    "send reminders"
  ],
  "jobs": [
    {
      "name": "import bank data",
      "does": "connect to bank accounts and import transaction data",
      "parts": [
        {
          "kind": "code-app",
          "search": ["bank import", "bank data import"]
        },
        {
          "kind": "device",
          "search": ["smart home finance", "finance automation"]
        }
      ]
    },
    {
      "name": "track spending",
      "does": "log and categorize transactions",
      "parts": [
        {
          "kind": "code-app",
          "search": ["transaction tracker", "expense tracker"]
        },
        {
          "kind": "data-template",
          "search": ["expense log template", "transaction log"]
        }
      ]
    },
    {
      "name": "set monthly budgets",
      "does": "create and enforce monthly spending limits",
      "parts": [
        {
          "kind": "code-app",
          "search": ["budget planner", "monthly budget"]
        },
        {
          "kind": "knowledge",
          "search": ["personal finance", "budgeting strategies"]
        }
      ]
    },
    {
      "name": "plan for Christmas",
      "does": "track and allocate funds for holiday expenses",
      "parts": [
        {
          "kind": "code-app",
          "search": ["holiday budget planner", "gift budget"]
        },
        {
          "kind": "data-template",
          "search": ["holiday spending plan", "gift budget spreadsheet"]
        }
      ]
    },
    {
      "name": "plan for summer camp",
      "does": "track and allocate funds for summer activities",
      "parts": [
        {
          "kind": "code-app",
          "search": ["summer camp budget", "activity budget"]
