        {
          "kind": "data-template",
          "search": ["summer camp expense tracker", "activity budget template"]
        }
      ]
    },
    {
      "name": "pay down credit card",
      "does": "manage and automate credit card payments",
      "parts": [
        {
          "kind": "code-app",
          "search": ["credit card payment planner", "debt repayment"]
        },
        {
          "kind": "knowledge",
          "search": ["debt management", "credit card repayment strategies"]
        }
      ]
    },
    {
      "name": "see charts",
      "does": "generate visual representations of spending data",
      "parts": [
        {
          "kind": "code-app",
          "search": ["data visualization", "chart generator"]
        },
        {
          "kind": "knowledge",
          "search": ["data visualization techniques", "chart types"]
        }
      ]
    },
    {
      "name": "send reminders",
      "does": "notify about upcoming bills and deadlines",
      "parts": [
        {
          "kind": "code-app",
          "search": ["reminder app", "automated reminders"]
        },
        {
          "kind": "knowledge",
          "search": ["reminder strategies", "automated reminder systems"]
        }
      ]
    }
  ]
}
